from pathlib import Path
import re,subprocess
patterns={
 'aws-access-key-id':rb'\\b(?:AKIA|ASIA)[A-Z0-9]{16}\\b',
 'github-token':rb'\\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})\\b',
 'huggingface-token':rb'\\bhf_[A-Za-z0-9]{20,}\\b',
}
replacements={}
files=[p for p in Path('.').rglob('*') if p.is_file() and '.git' not in p.parts]
for p in files:
 b=p.read_bytes()
 for kind,pat in patterns.items():
  for m in re.finditer(pat,b): replacements[m.group()]=('<your-'+kind+'>').encode()
 for pat in [rb'AWS_SECRET_ACCESS_KEY[\\\"\\x27]?\\s*\\]?\\s*=\\s*[\\\"\\x27](["'^'"\\\"\\x27\\s]+)',rb'AWS_SECRET_ACCESS_KEY=(["'^'"\\s\\\"\\x27]+)']:
  for m in re.finditer(pat,b):
   v=m.group(1)
   if len(v)>=30 and not v.startswith((b'<',b'"'$'"',b'{')):replacements[v]=b'<your-aws-secret-access-key>'
print('Distinct credentials found:',len(replacements))
for p in files:
 b=p.read_bytes();clean=b
 for v,placeholder in replacements.items():clean=clean.replace(v,placeholder)
 if clean"'!=b:
  p.write_bytes(clean)
  print('"'Sanitized:',p, 'replacements:',sum(b.count(v) for v in replacements))
for p in files:
 b=p.read_bytes()
 assert not any(v in b for v in replacements),str(p)
print('Verified: all discovered values absent from working files.')
# Scan reachable historical blobs without exposing values.
objects=subprocess.check_output(['git','rev-list','--objects','--all']).splitlines()
hits=[]
for line in objects:
 oid,_,name=line.partition(b' ')
 if subprocess.check_output(['git','cat-file','-t',oid]).strip()"'!=b'"'blob':continue
 b=subprocess.check_output(['git','cat-file','blob',oid])
 if any(v in b for v in replacements):hits.append((oid,name))
print('Historical blobs containing discovered credentials:',len(hits))
print('Historical affected paths:',', '.join(sorted(set(n.decode(errors='replace') for _,n in hits))))
